// ─────────────────────────────────────────────────────────────────────────────
// Справочник грамматики корейского: 0급 → 2급
//
// Охват выбран по тому, где человек застревает и уходит искать ответ наружу:
// правила чтения (их не «учат», но без них не читается ни один пример) и вся
// грамматика до уверенного 2급 — то есть до момента, когда предложения
// перестают быть однословными, а речь получает время, модальность и связки.
//
// ЧЕМ ЭТО НЕ ЯВЛЯЕТСЯ. Это не пересказ учебника и не замена курсу: порядок здесь
// не учебный, а справочный — по разделам и уровню, чтобы форму можно было найти,
// а не пройти. Что учить дальше, по-прежнему говорит курс (kohg → kotp → kot2),
// и у каждой формы записан юнит, где её проходят.
//
// ПРИМЕРЫ. У каждой формы их десять и больше, и у каждого подписана ситуация.
// Это главная работа файла: форму «~아/어서» по одному примеру не отличить от
// «~(으)니까», а по десяти — видно, что первая не встаёт перед просьбой.
//
// ТЕКСТЫ АВТОРСКИЕ. Перечень тем и их порядок авторским правом не охраняются;
// ни одного чужого объяснения, диалога или упражнения здесь нет.
// ─────────────────────────────────────────────────────────────────────────────

