    rule: `После 받침, звучащего как ㄱ, ㄷ или ㅂ, простая согласная следующего слога становится напряжённой: ㄱ→ㄲ, ㄷ→ㄸ, ㅂ→ㅃ, ㅅ→ㅆ, ㅈ→ㅉ. Пишется 학교, читается «хаккё»; пишется 식당, читается «сиктан(г)» с напряжённым ㄸ.

Напряжённая согласная — это не долгая и не удвоенная. Голосовые связки сжимаются перед звуком, воздух выходит резко и без придыхания; по-русски похожего звука нет вовсе, и именно поэтому русскоязычные слышат 학교 как «хакё» и теряют половину слова.

Правило автоматическое: его не нужно помнить пословно, оно срабатывает на любом стыке. Дополнительно напряжение появляется в двух местах, которые уже приходится помнить: после 받침 ㄹ в части ханча-слов (발전 — «пальччон») и в определительной форме на ~(으)ㄹ (할 거예요 — «халь ккоеё»).`,
