    unit: 'kotp-12',
    rule: `은/는 не показывает, кто действует. Она показывает, что слово — тема разговора: «что касается X, то…». Отсюда её два рабочих смысла.

Первый — представить или сменить тему. 저는 안나예요 «что до меня, я Анна». В начале разговора почти всегда 저는.

Второй — противопоставить, часто без произнесённой второй части. 커피는 좋아해요 значит «кофе-то я люблю» — и корейское ухо услышит невысказанное «а вот чай нет». Это не оттенок, а полноценный смысл: поставив 는 не туда, вы сообщаете противопоставление, которого не имели в виду.

Отсюда практическое правило: 은/는 — для известного, уже введённого, общего; 이/가 — для нового, конкретного, отвечающего на вопрос «кто именно».

Частица заменяет собой 이/가 и 을/를, а не добавляется к ним: не 저는이, а просто 저는. Зато с 에, 에서, 하고 она уживается: 학교에는, 집에서는.`,
