    rule: `У 에서 два смысла, и оба выводятся из одного образа: площадка, на которой или с которой что-то происходит.

Первый — место действия. Если в предложении есть настоящий глагол действия (работать, есть, учиться, встречаться), место оформляется через 에서: 식당에서 밥을 먹어요.

Второй — исходная точка. 어디에서 왔어요? «откуда вы приехали?», 한국에서 왔어요 «из Кореи». В паре с 까지 даёт маршрут: 집에서 학교까지 «от дома до школы».

Разграничение с 에 механическое и надёжное: посмотрите на глагол. Движение и положение (가다, 오다, 있다, 살다) → 에. Действие (하다, 먹다, 공부하다, 일하다, 만나다) → 에서.

Исключение, которое ломает механику и потому запоминается отдельно: 살다 «жить» допускает оба варианта. 서울에 살아요 — нейтрально; 서울에서 살아요 подчёркивает жизнь как процесс.

В разговоре 에서 часто сокращают до 서: 어디서 만날까요?`,
