    attach: 'перед существительным',
    unit: 'kotp-06',
    rule: `Указательных в корейском три, а не два. 이 — рядом с говорящим, 그 — рядом с собеседником или уже упомянутое, 저 — далеко от обоих, но видимое.

Эта система важнее, чем кажется: 그 покрывает не только «то, что у тебя», но и «то, о чём мы только что говорили». Именно 그 переводит русское «тот самый»: 그 영화 봤어요? «ты смотрел тот фильм?».

Указательное слово не стоит само по себе — за ним обязано идти существительное: 이 책 «эта книга». Чтобы сказать просто «это», нужно 것: 이것, 그것, 저것; в разговоре они стягиваются в 이거, 그거, 저거.

Со связкой и частицами стяжения идут дальше: 이것이 → 이게, 이것은 → 이건, 이것을 → 이걸. В речи употребляются почти только короткие формы.

От той же тройки образуются места (여기, 거기, 저기) и способы (이렇게, 그렇게, 저렇게).`,
