    rule: `Основная форма будущего времени. После гласной — ~ㄹ 거예요 (갈 거예요), после согласной — ~을 거예요 (먹을 거예요). Читается с напряжением: «каль ккоеё».

Первое значение — план или намерение: 내일 갈 거예요 «завтра пойду». Это нейтральное будущее, которым говорят о собственных делах.

Второе — предположение о третьем лице или о том, чего не знаешь наверняка: 지금 자고 있을 거예요 «он, наверное, спит». По форме не отличить, различает контекст и лицо: о себе — план, о других — догадка.

В прошедшем даёт «наверное, было»: 갔을 거예요 «наверное, ушёл».

Разговорный вариант — ~(으)ㄹ 거야 в панмале и ~(으)ㄹ 겁니다 в официальном стиле.`,
