    rule: `~아/어 있다 описывает состояние, в котором предмет остался после действия: 문이 열려 있어요 «дверь открыта» (её открыли, и она так и стоит).

Ключевое ограничение: форма работает только с непереходными глаголами — теми, у которых нет прямого дополнения. 앉다, 서다, 눕다, 남다, 열리다, 닫히다. Сказать 밥을 먹어 있어요 нельзя.

Отсюда пара, которую и стоит запомнить: 앉고 있어요 «садится (процесс)» — 앉아 있어요 «сидит (результат)». 서고 있어요 «встаёт» — 서 있어요 «стоит».

Отсюда же связка с пассивом: чаще всего эта форма встречается именно с пассивными глаголами на 이/히/리/기 — 켜져 있다 «включено», 놓여 있다 «положено», 쓰여 있다 «написано».

Практическая ценность формы — описание обстановки: что где стоит, открыто, включено, оставлено.`,
