    rule: `Время — единственное место, где оба ряда числительных встречаются в одной фразе. Часы считаются корейским рядом (한 시, 두 시, 세 시), минуты — китайским (십 분, 삼십 분).

Это не логика, а историческая случайность, и её проще запомнить примером: 세 시 삼십 분 «три тридцать». Первое число корейское, второе китайское.

Половина — 반: 세 시 반. «Без пяти» — 오 분 전: 세 시 오 분 전.

До полудня и после — 오전 / 오후, и они ставятся ПЕРЕД временем: 오후 세 시.

Время события оформляется частицей 에: 세 시에 만나요. Но в вопросе 몇 시예요? частицы нет — там время не событие, а сам предмет разговора.`,
