    rule: `Дата пишется и произносится от большего к меньшему: 2026년 8월 22일. Всё — китайским рядом.

Два месяца читаются нерегулярно и запоминаются отдельно: июнь — 유월 (не 육월), октябрь — 시월 (не 십월). Причина фонетическая: конечный согласный выпал, чтобы слово произносилось легче.

Дни недели: 월요일 (пн), 화요일 (вт), 수요일 (ср), 목요일 (чт), 금요일 (пт), 토요일 (сб), 일요일 (вс). Первый слог — это ханча-корень: луна, огонь, вода, дерево, металл, земля, солнце.

Вопросы: 며칠이에요? «какое число?», 무슨 요일이에요? «какой день недели?». Обратите внимание, что для числа употребляется 며칠, а не 몇 일.

Событие с датой оформляется частицей 에: 팔월 이십이 일에 만나요. Слова 오늘, 어제, 내일 — без неё.`,
