    attach: 'к основе глагола',
    unit: 'kotp-25',
    rule: `Отрицательное побуждение образуется только этой формой: 가지 마세요 «не уходите». Сказать 안 가세요 в значении «не ходите» нельзя — это будет вопросом «вы не идёте?».

Строится всегда одинаково: основа + 지 마세요, без гармонии гласных и без вставного 으. 먹지 마세요, 하지 마세요, 열지 마세요.

Регистры: 지 마 (панмаль), 지 마세요 (вежливо), 지 마십시오 (официально, на табличках), 지 말아 주세요 (просьба, мягче запрета).

В соединении с другим действием — 지 말고: 여기서 먹지 말고 밖에서 드세요 «не ешьте здесь, поешьте на улице».

С существительными запрет выражается иначе — через 금지: 촬영 금지 «съёмка запрещена». Это язык табличек, а не разговора.`,
    examples: [
      { text: '가지 마세요.', ru: 'Не уходите.', when: 'Просьба остаться' },
      { text: '걱정하지 마세요.', ru: 'Не волнуйтесь.', when: 'Успокаивая' },
      { text: '늦지 마세요.', ru: 'Не опаздывайте.', when: 'Договариваясь о встрече' },
      { text: '여기서 담배 피우지 마세요.', ru: 'Здесь не курите.', when: 'Замечание' },
      { text: '만지지 마세요.', ru: 'Не трогайте.', when: 'В музее, в магазине' },
      { text: '잊지 마세요.', ru: 'Не забудьте.', when: 'Напоминание' },
      { text: '문을 열지 마십시오.', ru: 'Не открывайте дверь.', when: 'Официально, на табличке' },
      { text: '너무 무리하지 마세요.', ru: 'Не перенапрягайтесь.', when: 'Забота о больном' },
      { text: '울지 마.', ru: 'Не плачь.', when: 'Панмаль, близкому' },
      { text: '여기서 먹지 말고 밖에서 드세요.', ru: 'Не ешьте здесь, поешьте снаружи.', when: 'Запрет с альтернативой' },
    ],
    pitfall: 'Пытаться запретить через 안: 안 가세요 значит «вы не идёте?», а не «не ходите». У побуждения своё отрицание.',
