    unit: 'kotp-33',
    rule: `~아/어도 돼요 значит «можно»: 가도 돼요? «можно идти?». Буквально — «даже если сделать, становится нормально».

Вопрос и ответ строятся одной формой: 앉아도 돼요? — 네, 앉아도 돼요. Отказ даётся другой конструкцией — 안 돼요 или ~(으)면 안 돼요.

Вежливее — 아/어도 될까요?: «можно ли мне…». Так спрашивают у начальника, у преподавателя, у незнакомого.

Вместо 되다 встречаются 괜찮다 и 좋다 с тем же смыслом: 앉아도 괜찮아요? Разница невелика, 되다 самое нейтральное.

Обратите внимание, что это разрешение, а не возможность: «я могу поднять этот чемодан» — это ~(으)ㄹ 수 있어요, а не 들어도 돼요.`,
