    rule: `~(으)면 안 돼요 — «нельзя»: 여기서 담배를 피우면 안 돼요. Буквально «если сделать, то не годится».

Это стандартный отказ на просьбу 아/어도 돼요?: 여기 앉아도 돼요? — 죄송하지만 앉으면 안 돼요.

Вопросительная форма 면 안 돼요? даёт мягкую просьбу: 좀 도와주면 안 돼요? «может, всё-таки поможешь?».

Отрицание внутри условия даёт обязанность: 안 가면 안 돼요 «нельзя не пойти», то есть «надо пойти». Двойное отрицание в корейском работает так же, как в русском, и звучит так же настойчиво.

На табличках вместо разговорной формы стоят 금지 и ~지 마십시오, но в речи именно ~(으)면 안 돼요.`,
