    rule: `~고 싶어요 значит «хочу»: 가고 싶어요 «хочу пойти». Форма ставится только к глаголам действия; «хочу воды» — это не 물고 싶어요, а 물을 마시고 싶어요 или просто 물을 주세요.

Ключевое ограничение: ~고 싶다 говорится о себе и, в вопросе, о собеседнике. О третьем лице нужна другая форма — ~고 싶어 하다: 동생이 가고 싶어 해요 «брат хочет пойти».

Причина в устройстве языка: корейский разделяет то, что говорящий знает изнутри (своё желание), и то, что он наблюдает снаружи (чужое). Сказать 동생이 가고 싶어요 — значит заявить, что вы читаете чужие мысли.

Дополнение при желании может стоять и с 을/를, и с 이/가: 물을 마시고 싶어요 и 물이 마시고 싶어요. Второе чуть эмоциональнее.

Прошедшее — 고 싶었어요 «хотел». Отрицание — 고 싶지 않아요 или разговорное 하기 싫어요 «неохота».`,
