    rule: `~(으)ㄴ 적이 있다 сообщает, что событие когда-либо случалось: 한국에 간 적이 있어요 «мне доводилось бывать в Корее». Отрицание — 적이 없어요.

적 — это существительное «случай, раз», поэтому конструкция буквально значит «есть случай, когда я это делал».

Отличие от простого прошедшего важно: 한국에 갔어요 «я ездил в Корею» сообщает о конкретной поездке, а 간 적이 있어요 — о наличии опыта вообще. Поэтому о вчерашнем дне так не говорят: 어제 간 적이 있어요 звучит странно.

Часто соединяется с ~아/어 보다, и это самая естественная форма вопроса об опыте: 먹어 본 적이 있어요? «доводилось ли пробовать?».

Для недавнего и повторяющегося события форма не годится — она подразумевает, что случай был редким или давним.`,
