    rule: `~지만 значит «но»: 비싸지만 맛있어요 «дорого, но вкусно». Приклеивается к основе без изменений, гармонии гласных нет.

В отличие от ~고, время здесь ставится в каждой части, где оно нужно: 어제는 갔지만 오늘은 안 가요 «вчера ходил, но сегодня не иду».

Со связкой — 이지만: 학생이지만 일도 해요 «студент, но и работает».

Устойчивое смягчение просьбы: 죄송하지만… «извините, но…», 실례지만… «прошу прощения, но…». С них начинается обращение к незнакомому — вопрос о дороге, просьба уступить место.

Отличие от ~는데 существенно: ~지만 — прямое противопоставление, ~는데 чаще просто фон, «дело в том, что». Русское «но» покрывает оба, и потому русскоязычные ставят 지만 там, где кореец сказал бы 는데.`,
