    rule: `У ~아/어서 два значения, и оба важны.

Причина: 늦어서 죄송해요 «извините, что опоздал», 비가 와서 못 갔어요 «не пошёл, потому что был дождь».

Связанная последовательность: первое действие создаёт условие для второго и они происходят с одним и тем же предметом. 친구를 만나서 영화를 봤어요 «встретился с другом и посмотрел с ним фильм».

Два жёстких ограничения, которые и отличают форму от ~(으)니까.

Первое: время в первой части не ставится. «Так как вчера был дождь» — 어제 비가 와서, а не 왔어서.

Второе: после ~아/어서 не может стоять просьба, приказ или предложение. Нельзя сказать 시간이 없어서 빨리 가세요. Для этого есть ~(으)니까: 시간이 없으니까 빨리 가세요.

Зато в извинениях и благодарностях употребляется именно 아/어서: 도와주셔서 감사합니다.`,
