    unit: 'kotp-27',
    rule: `~(으)면 покрывает и «если», и «когда» в значении повторяющегося условия: 비가 오면 안 가요 «если пойдёт дождь, не пойду»; 봄이 오면 꽃이 펴요 «когда приходит весна, цветут цветы».

Русское различие «если» и «когда» корейский здесь не проводит: разделяет контекст, а не форма.

С прошедшим — нереальное или уже свершившееся условие: 알았으면 말했을 거예요 «если бы знал, сказал бы».

Частые связки: ~(으)면 좋겠어요 «хорошо бы», ~(으)면 안 돼요 «нельзя», ~(으)면 돼요 «достаточно, годится», ~(으)면 어때요? «а если так?».

Отличие от ~(으)ㄹ 때 в том, что 면 говорит об условии («в случае, если»), а 때 — о моменте («в тот момент, когда»). 한국에 가면 연락하세요 «если поедешь в Корею, свяжись»; 한국에 갈 때 연락하세요 «когда поедешь, свяжись».`,
