    rule: `~(으)ㄹ 때 значит «когда, во время»: 밥을 먹을 때 «когда ем», 어릴 때 «когда был маленьким».

Форма всегда стоит с ~(으)ㄹ, даже если речь о прошлом: 학생일 때 «когда был студентом». Прошедшее ~았/었을 때 появляется тогда, когда действие УЖЕ закончилось к моменту второго: 도착했을 때 전화하세요 «позвоните, когда доедете».

Разница между 갈 때 и 갔을 때 практическая и заметная: 한국에 갈 때 «по пути в Корею», 한국에 갔을 때 «когда уже был в Корее».

Со связкой — 일 때: 방학일 때, 학생일 때.

Существительные времени идут без формы: 방학 때, 시험 때, 점심 때 — просто 때 после существительного.`,
