    unit: 'kotp-33',
    rule: `~(으)면서 значит «делая одновременно»: 음악을 들으면서 공부해요 «занимаюсь, слушая музыку».

Два жёстких требования: подлежащее у обеих частей одно и то же, и действия действительно идут одновременно. «Пока он спал, я работал» так не скажешь — там нужно ~는 동안.

Главное действие ставится ВТОРЫМ. 음악을 들으면서 공부해요 — это про учёбу под музыку, а 공부하면서 음악을 들어요 — про слушание музыки во время учёбы. Русский порядок обычно обратный, и это частая причина странно звучащих фраз.

Время не ставится в первую часть: 어제 음악을 들으면서 공부했어요.

Второе значение — противоречие: 알면서 모른 척해요 «знает, а делает вид, что нет». Здесь форма близка к «хотя».`,
