    attach: 'к определительной форме',
    unit: 'kot2-16',
    rule: `~는 것 같다 значит «кажется, похоже»: 비가 오는 것 같아요 «кажется, идёт дождь».

Время различается определительной формой: 온 것 같아요 «кажется, прошёл», 오는 것 같아요 «кажется, идёт», 올 것 같아요 «кажется, пойдёт».

Прилагательные берут ~(으)ㄴ: 좋은 것 같아요, 예쁜 것 같아요.

Второе, и очень важное, употребление — смягчение собственного мнения. Кореец редко говорит «мне нравится» прямо; естественнее 좋은 것 같아요 «мне кажется, это хорошо». Это не неуверенность, а вежливость: прямое суждение звучит категорично.

Отсюда практическое правило для разговора: почти любое оценочное высказывание безопаснее закончить 것 같아요.

Соседние формы предположения: ~나 보다 (по косвенным признакам), ~(으)ㄹ 것이다 (уверенная догадка), ~겠~ (мгновенная реакция).`,
