    rule: `처럼 и 같이 значат «как, подобно»: 한국 사람처럼 말해요 «говорит как кореец». Обе равнозначны, 처럼 чуть частотнее.

Не путайте 같이 «как» с 같이 «вместе» — это одно слово в двух ролях, различает позиция: 친구같이 «как друг», 친구하고 같이 «вместе с другом».

Отрицательное сходство — 같지 않다 или 처럼 안: 한국 사람 같지 않아요.

Родственная форма — ~같다 в конце: 꿈 같아요 «как сон», 거짓말 같아요 «похоже на враньё».

Для равной меры есть 만큼: 저만큼 «столько же, сколько я», 생각만큼 «настолько, насколько ожидал». Отличие от 처럼 в том, что 만큼 говорит о количестве, а 처럼 — о способе и виде.`,
