    title: 'Наречие от прилагательного',
    short: 'Быстрый → быстро, красивый → красиво',
    attach: 'к основе прилагательного',
    rule: `~게 превращает прилагательное в наречие: 빠르다 → 빠르게 «быстро», 예쁘다 → 예쁘게 «красиво», 맛있다 → 맛있게 «вкусно».

Это регулярный способ, и он работает почти со всеми прилагательными. Но у части слов есть свои наречные формы, и они употребительнее: 빨리 (быстро), 많이 (много), 일찍 (рано), 늦게 (поздно), 잘 (хорошо). 빨리 и 빠르게 оба существуют, но в быту чаще первое.

Второе значение ~게 — «так, чтобы»: 안 보이게 놓으세요 «положите так, чтобы не было видно».

Устойчивые формулы: 맛있게 드세요 «приятного аппетита», 재미있게 보내세요 «хорошо провести время», 건강하게 지내세요 «будьте здоровы». Ими прощаются и желают — стоит выучить целиком.

Есть и ~게 하다 «заставить, сделать так, чтобы»: 웃게 했어요 «рассмешил».`,
