    short: 'Изменение признака во времени',
    attach: 'к основе прилагательного',
    unit: 'kot2-10',
    rule: `~아/어지다 присоединяется к прилагательному и превращает признак в процесс изменения: 좋다 «хороший» → 좋아지다 «становиться лучше», 춥다 → 추워지다 «холодать».

Употребляется чаще всего в прошедшем — как констатация перемены: 날씨가 추워졌어요 «похолодало», 한국어가 쉬워졌어요 «корейский стал даваться легче».

С глаголами та же форма даёт пассив или самопроизвольность: 만들어지다 «изготавливаться», 켜지다 «включаться». Это уже другая тема, но форма выглядит одинаково.

Соседняя конструкция ~게 되다 работает с глаголами и значит «так вышло, что»: 한국에 살게 됐어요 «так получилось, что живу в Корее».

Различать просто: 지다 — про признак (какой), 게 되다 — про действие (что делаю).`,
