    rule: `~(으)시~ вставляется между основой и окончанием и поднимает того, О КОМ идёт речь: 선생님이 가십니다, 어디 가세요?.

Ключевое отличие от речевых стилей: стиль (해요체 / 합니다체) настраивает отношение к СЛУШАТЕЛЮ, гоноратив — к ПОДЛЕЖАЩЕМУ. Поэтому они независимы: можно сказать 선생님이 가셨어 — уважительно о учителе, но панмалем к приятелю.

О себе гоноратив не употребляется никогда.

Ряд глаголов заменяется целиком: 먹다 → 드시다, 자다 → 주무시다, 있다 → 계시다, 말하다 → 말씀하시다, 죽다 → 돌아가시다.

Поднимаются и связанные с человеком предметы: 말씀 (слово), 성함 (имя), 연세 (возраст), 댁 (дом). 성함이 어떻게 되세요? — вежливый способ спросить имя.

Подлежащее при гоноративе берёт частицу 께서 вместо 이/가: 아버지께서 오셨어요. В разговоре часто оставляют 이/가 — это допустимо.`,
