    rule: `~네요 выражает то, что говорящий обнаружил прямо сейчас: 날씨가 춥네요 «а холодно-то». Без него фраза 날씨가 추워요 звучит как констатация, а с ним — как живая реакция.

~군요 (в панмале ~구나) значит примерно то же, но с оттенком «ах вот как», понимания чего-то нового из чужих слов: 아, 그렇군요 «а, вот оно что».

Различие практическое: 네요 — реакция на то, что видишь и чувствуешь сам, 군요 — на то, что тебе рассказали.

С глаголами 군요 берёт форму ~는군요: 가는군요. С прилагательными и связкой — просто 군요: 좋군요, 학생이군요.

Эти окончания делают речь живой. Учебник даёт нейтральные формы, и человек с одними 해요체 звучит как справочная служба; 네요 — самый дешёвый способ это исправить.`,
