    unit: 'kot2-03',
    rule: `~잖아요 напоминает собеседнику о том, что он и так знает: 어제 말했잖아요 «я же вчера говорил». Это не нейтральная форма: в ней есть лёгкий упрёк, и с начальником или незнакомым она звучит дерзко.

~지요 (в разговоре ~죠) ищет согласия: 오늘 춥지요? «сегодня холодно, правда?». Здесь наоборот — форма мягкая и располагающая.

Второе значение 죠 — мягкое подтверждение своего: 네, 그렇죠 «да, конечно». И третье — вежливое предложение: 같이 가시죠.

Практическая разница: 잖아요 говорит «ты это знал», 지요 говорит «мы оба так думаем». Первое давит, второе объединяет.

Иностранцу безопаснее начать с 죠 и осторожно относиться к 잖아요 — по регистру она ближе к разговору между своими.`,
