    rule: `Гласная ㅡ в конце основы выпадает перед окончанием на 아/어. Дальше смотрим на гласную ПРЕДЫДУЩЕГО слога: если это ㅏ или ㅗ — берём 아요, иначе 어요.

바쁘다 → 바ㅃ + 아요 = 바빠요. 예쁘다 → 예ㅃ + 어요 = 예뻐요. 크다 → ㅋ + 어요 = 커요 (предыдущего слога нет, значит 어요).

Это самый регулярный из неправильных типов и самый частый: 쓰다, 크다, 바쁘다, 예쁘다, 기쁘다, 슬프다, 아프다, 배고프다, 모으다.

Перед окончаниями, начинающимися с согласной или с 으, ничего не происходит: 바쁘고, 바쁘지만, 바쁩니다.

Отдельно стоит запомнить 아프다 → 아파요 «болит» и 배고프다 → 배고파요 «голоден» — это фразы, которые нужны каждый день.`,
