    rule: `~아/어 놓다 значит, что действие сделано заранее и его результат сохраняется: 창문을 열어 놓았어요 «открыл окно (и оно так и стоит открытым)».

~아/어 두다 значит почти то же; разница в оттенке. 놓다 — «сделал и оставил как есть», 두다 — «сделал и приберёг на будущее». 예매해 뒀어요 звучит как «билеты заранее взял, пусть будут».

В отличие от ~아/어 있다, эта форма работает с ПЕРЕХОДНЫМИ глаголами: там, где есть 을/를. 문을 열어 놓다 (я открыл и оставил) против 문이 열려 있다 (дверь открыта).

В разговоре стягивается: 놓았어요 → 놨어요, 두었어요 → 뒀어요.

Практическая ценность формы — вся бытовая подготовка: заранее купить, забронировать, приготовить, записать, включить.`,
