    title: 'Только, всего лишь (с отрицанием)',
    short: 'Ограничение, которое обязательно требует отрицания',
    attach: 'к существительному',
    rule: `밖에 значит «только», но, в отличие от 만, ТРЕБУЕТ отрицательного сказуемого: 천 원밖에 없어요 «у меня только тысяча вон».

Буквально 밖 — это «вне»: «вне тысячи вон ничего нет». Отсюда и обязательное отрицание, и оттенок — «мало, меньше, чем нужно».

Сравните: 천 원만 있어요 — нейтральная констатация, «есть ровно тысяча»; 천 원밖에 없어요 — «всего тысяча, этого мало». Второе несёт оценку.

Как и 만, вытесняет 은/는, 이/가, 을/를 и уживается с 에, 에서.

Частые связки: 한 명밖에 없어요, 조금밖에 못 했어요, 이것밖에 안 남았어요.`,
